import{_ as e,c as a,a2 as p,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第十三章 要知道控制自己的食量","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/13第十三章 要知道控制自己的食量.md","filePath":"meditation/巴利文大藏经/13第十三章 要知道控制自己的食量.md"}'),_={name:"meditation/巴利文大藏经/13第十三章 要知道控制自己的食量.md"};function r(n,t,i,s,d,c){return o(),a("div",null,t[0]||(t[0]=[p('<h1 id="第十三章-要知道控制自己的食量" tabindex="-1">第十三章 要知道控制自己的食量 <a class="header-anchor" href="#第十三章-要知道控制自己的食量" aria-label="Permalink to &quot;第十三章 要知道控制自己的食量&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部3相应13经/一桶煮好的经(憍萨罗相应/有偈篇/祇夜)</p><p>有个时候，骄萨罗国的波斯匿王每天都要吃很多饭菜，他长的肥硕无比，稍微做点运动就会汗如雨下，有一天，波斯匿王吃完饭后，就来到佛陀的住所，顶礼佛陀后，他在一旁坐下。</p><p>那时，佛陀看见肥头胖耳的波斯匿王汗流浃背、气喘吁吁的用毛巾不住的擦着头上和身上的汗，佛陀就对他说：“大王，有智慧的人会经常在内心中生起正念，他们知道控制自己每天的食量，他们知道不暴饮暴食，合理的膳食是能够减少各种病痛对自己身体的侵袭和折磨的。他们知道控制自己每天的食量，合理的膳食是可以减缓自己的衰老，延长自己的寿命的。</p><p>这时，佛陀说偈言：</p><p>「以常持正念，取食知量人。</p><p>则少有其苦，迟老得寿长。」</p><p>波斯匿王听到佛陀的教导后，就对站在他身后的年轻人善见说到：“善见，以后你在我每天吃饭的时候，就念诵世尊的这句偈颂，我会每天都赏赐你一百元的。”</p><p>善见恭敬的回答：“陛下，谨尊您的诏命。”于是善见就记下了佛陀的这句偈语，每当波斯匿王吃饭的时候，善见就会在波斯匿王的旁边念诵：</p><p>「以常持正念，取食知量人。</p><p>则少有其苦，迟老得寿长。」</p><p>波斯匿王一旦听到佛陀的偈颂，就会逐渐减少食量，过了一段时间，波斯匿王身上的赘肉开始慢慢变少，他身上结实的肌肉开始显露出来，波斯匿王对自己虎背熊腰壮硕的身体非常的满意，他在御花园一边舞剑一边欢喜的说到：“世尊慈悲的教导，真的是让我现在和未来都获益匪浅呀！”</p>',13)]))}const f=e(_,[["render",r]]);export{m as __pageData,f as default};
